 function axes(p){const out=[];for(let i=0;i<p.length;i++){const a=p[i],b=p[(i+1)%p.length],dx=b[0]-a[0],dy=b[1]-a[1],n=Math.hypot(dx,dy);if(n>1e-10)out.push([-dy/n,dx/n]);}return out;}
 function range(p,n){let lo=Infinity,hi=-Infinity;for(const q of p){const d=q[0]*n[0]+q[1]*n[1];lo=Math.min(lo,d);hi=Math.max(hi,d);}return[lo,hi];}
